  ? [...new Set(selectedLegacyDates.map(dayOfWeekFromDate))].sort((a, b) => a - b)
  : ((form.days_of_week || []).length ? form.days_of_week : []);
const daysOfWeek = inferredDays.map(Number).filter((d) => d >= 1 && d <= 7);
const firstClassDate = isBackfillMode
  ? (selectedLegacyDates[0] || form.first_class_date || todayYmd())
  : (form.first_class_date || null);

// ...
sessions_used: isBackfillMode ? 0 : sessionsUsed,
remaining_sessions: isBackfillMode ? sessionsPurchased : remaining,
first_class_date: firstClassDate,
days_of_week: daysOfWeek,
```

